<?php declare(strict_types=1);
namespace Kulturhus\Verein\Web;
use Kulturhus\Verein\WorkspaceAccess;
/** Fixed read-only guidance. Links retain the ordinary destination's permission checks. */
final class TaskHelp
{
 public const TOPICS=[
  'social-conversations'=>['title'=>'Social-Nachrichten und Kommentare beantworten','intro'=>'Die Gesprächsansicht verbindet ursprüngliche Fragen mit selbst geschriebenen Antworten. Namen, Nachrichten und Notizen bleiben in beiden Oberflächensprachen unverändert.','steps'=>['Öffne Social Media & Newsletter → Interaktionen und wähle Nachrichten oder Kommentare. Suche und Filter prüfen den gespeicherten Bestand; sechs Gespräche pro Seite und die Seitenwahl funktionieren auch ohne JavaScript.','Öffne die ursprüngliche Frage und schreibe deine eigene Antwort. Senden beauftragt den Anbieter bewusst; Entwurf speichern bleibt privat. Aktuelle Bearbeitungs- und Versandrechte sowie bei privaten Meta-Nachrichten das tatsächliche 24-Stunden-Fenster bleiben erforderlich.','Prüfe das tatsächliche Ergebnis im Verlauf. Bei Ergebnis unklar nicht erneut senden. Nutze Ergebnis prüfen, soweit angeboten, und vergleiche das Anbieteroriginal. Eine angenommene ursprüngliche Wiederholung erzeugt keine zweite Nachricht.','Nach einer Ablehnung bleiben Text und ursprünglicher Vorgang erhalten. Prüfe Original, Verbindung und Rechte. Neu prüfen sendet selbst nichts; eine weitere Nachricht bleibt eine bewusste Aktion. Frühere Fassungen dienen ausschließlich zum Lesen.','Optionen → Mailmodul öffnet eigene Einstellungen, ohne eine ungesendete Antwort zu verwerfen. Abgewiesene Einstellungen behalten Adressen und ursprünglichen Stand. Gespeicherte Einstellungen prüfen liest den tatsächlichen Stand getrennt; ein Passwort erscheint nie im Formular.','Optionen → Abrufzeiten öffnet eigene Einstellungen und erhält deine ungesendete Antwort. Ergebnis prüfen speichert nichts. Nach einem Konflikt bereitet Aktuellen Stand vorbereiten deine Angaben für den aktuellen Plan vor; Zeiten speichern bleibt eine bewusste Aktion. Der Verlauf zeigt deine tatsächlich gespeicherten Änderungen.'],'guard'=>['view'=>'social'],'links'=>[['Nachrichten öffnen',['view'=>'social','section'=>'inbox'],''],['Kommentare öffnen',['view'=>'social','section'=>'review'],'']]],
  'calendar'=>['title'=>'Kalender und Termine verwenden','intro'=>'Vereinstermine und geplante Veröffentlichungen haben eigene Kalenderansichten.','steps'=>['Öffne Kalender und wähle den gewünschten Monat oder Zeitraum.','Öffne einen Termin, um Uhrzeit, Ort und Beteiligte zu prüfen. Beachte die angezeigte Zeitzone.','Verwende für Beiträge, Reels, Storys und Newsletter den Monatskalender unter Social & Newsletter.','Speichere einen eigenen Termin nur mit passender Berechtigung. Ein Website-Termin wird gesondert veröffentlicht.','Bei einem Ladefehler bleiben ungespeicherte Angaben im offenen Formular. Versuche den Vorgang erneut; prüfe vor einer Wiederholung den gespeicherten Stand.'],'guard'=>['view'=>'calendar'],'links'=>[['Kalender und Termine verwenden',['view'=>'calendar'],'']]],'inventory'=>['title'=>'Inventar und Ausleihe verwalten','intro'=>'Gegenstand, Standort, Ausleihe und Buchwert gehören zusammen und behalten ihre eigenen Nachweise.','steps'=>['Öffne Inventar & Ausleihe und suche den Gegenstand oder seinen Standort.','Prüfe Beschreibung, Kennzeichnung und vorhandene Belege, bevor du einen weiteren Gegenstand anlegst.','Ordne eine Anschaffung ihrer tatsächlichen Rechnung zu. Anschaffungswert und Abschreibung werden im Finanzbereich geprüft.','Erfasse eine Ausleihe mit Person und Rückgabetermin. Bestätige die tatsächliche Rückgabe gesondert.','Bei einem zwischenzeitlich geänderten Stand bleiben deine Angaben zur Prüfung erhalten. Öffne den aktuellen Gegenstand und bestätige die Änderung erneut.'],'guard'=>['view'=>'inventory','tab'=>'where'],'links'=>[['Inventar und Ausleihe verwalten',['view'=>'inventory','tab'=>'where'],'']]],'chat'=>['title'=>'Nachrichten und Umfragen verwenden','intro'=>'Der Vereinschat verbindet Unterhaltungen, Anhänge und Umfragen mit persönlichen Zugriffsrechten.','steps'=>['Öffne Chat und suche eine vorhandene Unterhaltung. Der Filter Ungelesen grenzt neue Nachrichten ein.','Wähle bei einer neuen Unterhaltung die Beteiligten bewusst aus. Neu hinzugefügte Personen können den bisherigen Verlauf lesen.','Prüfe Nachricht und Anhänge vor dem Senden. Antworten bleiben mit ihrer ursprünglichen Nachricht verbunden.','Erstelle eine Umfrage mit getrennten Antwortmöglichkeiten. Eine Abstimmung wird ausdrücklich gespeichert.','Bei Verbindungsproblemen bleibt deine Schreibeingabe erhalten. Lade neue Nachrichten erneut; Browserhinweise benötigen deine eigene Erlaubnis.'],'guard'=>['view'=>'chat'],'links'=>[['Nachrichten und Umfragen verwenden',['view'=>'chat'],'']]],'website'=>['title'=>'Website-Inhalte sicher bearbeiten','intro'=>'Speichern, Freigeben und Veröffentlichen sind getrennte Schritte.','steps'=>['Öffne Website und wähle Seiten, Aktuelles, Fotogalerie oder Veranstaltungen.','Suche den vorhandenen Inhalt. Titel, Adresse und eigene Feldbeschriftungen bleiben in ihrer ursprünglichen Sprache.','Speichere deine Änderungen als Entwurf und prüfe die Vorschau. Die bisherige Veröffentlichung bleibt bis zur erneuten Freigabe erhalten.','Veröffentliche nur mit passender Berechtigung. Prüfe bei einem geplanten Termin die Freigabe und den laufenden Veröffentlichungsdienst.','Bei einem Versionskonflikt vergleiche deinen Vorschlag mit dem aktuellen Stand. Papierkorb und gespeicherte Versionen bieten getrennte Wiederaufnahmewege.'],'guard'=>['view'=>'website','tab'=>'pages'],'links'=>[['Website-Inhalte sicher bearbeiten',['view'=>'website','tab'=>'pages'],'']]],'press'=>['title'=>'Pressemitteilungen vorbereiten','intro'=>'Entwurf, geprüfte Fassung und tatsächlicher Versand bleiben nachvollziehbar getrennt.','steps'=>['Öffne Presse und suche eine vorhandene Mitteilung oder lege einen neuen Entwurf an.','Trage Titel, Einleitung und Text ein. Wähle bei Bedarf eine Veranstaltung als Quelle und prüfe die übernommenen Angaben.','Wähle Empfänger und Fotoanlagen bewusst aus. Suche und Seitenwechsel behalten die vorhandene Auswahl.','Speichere den Entwurf und öffne die gespeicherte Fassung zur Prüfung. Freigabe und Versand erfolgen gesondert.','Bei unklarem Versandstatus prüfe zuerst den Zustellverlauf. Wiederhole keinen Versand allein wegen einer unterbrochenen Browserantwort.','Veranstaltung auswählen öffnet eine eigene Auswahl und erhält ungespeicherte Texte. Nach einer unterbrochenen Übernahme bleiben Auswahl und ursprünglicher Vorgang erhalten. Ergebnis prüfen legt keinen Entwurf an; unverändert wiederholen öffnet denselben bestätigten Entwurf. Weiteren eigenen Entwurf vorbereiten ist eine bewusste neue Übernahme.'],'guard'=>['view'=>'press','tab'=>'press'],'links'=>[['Pressemitteilungen vorbereiten',['view'=>'press','tab'=>'press'],'']]],'year-end'=>['title'=>'Jahresabschluss und DATEV prüfen','intro'=>'SKR42-Konten, EÜR oder Bilanz und Export müssen denselben geprüften Buchungsstand abbilden.','steps'=>['Prüfe zuerst offene Bankzuordnungen, Rechnungen und Beitragsforderungen. Eine vorbereitete Überweisung ist noch keine erfolgte Zahlung.','Wähle Abschlussjahr, Gewinnermittlungsart und den passenden Vereinsbereich. Prüfe Anfangsbestand, laufende Buchungen und Endbestand.','Prüfe Anlagenwerte, Abschreibungen und steuerliche Abweichungen anhand der ursprünglichen Belege. Interne Tagesaufteilung bestätigt kein steuerliches Teilmonatsverfahren.','Nicht qualifizierte Fälle für 72500 oder 72550 bleiben exportgesperrt. Eine Quellenaufnahme allein gibt diese steuerlichen Fälle nicht frei.','Vergleiche den DATEV-Export mit Buchungssummen und Belegen. Prüfe die Steuerdatei vor jeder gesondert bestätigten Übermittlung erneut.'],'guard'=>['view'=>'finance','tab'=>'tax'],'links'=>[['Jahresabschluss und DATEV prüfen',['view'=>'finance','tab'=>'tax'],'']]],'bank'=>['title'=>'Bankumsatz zuordnen','intro'=>'Verbinden Sie die tatsächlich erfolgte Zahlung mit ihrer Rechnung oder einem anderen passenden Vereinsbeleg.','steps'=>['Öffnen Sie Finanzen → Bank & Kasse und wählen Sie das richtige Konto.','Grenzen Sie die Umsätze über Suche, Zeitraum und Offen und teilweise ein. Öffnen Sie den tatsächlichen Umsatz.','Vergleichen Sie Person, Verwendungszweck und Betrag mit der Rechnung, dem Beitrag oder dem anderen Beleg. Ordnen Sie nur den tatsächlich passenden Teilbetrag zu.','Eine bereits übernommene Zahlung wird nicht noch einmal als neue Zahlung erfasst. Eine falsche Verbindung lösen Sie mit Grund über Zuordnung aufheben.'],'guard'=>['view'=>'finance','tab'=>'bank'],'links'=>[['Ausführliche Finanzhilfe öffnen',['view'=>'finance','tab'=>'help'],'bank-zuordnung'],['Noch zuzuordnende Umsätze öffnen',['view'=>'finance','tab'=>'bank','assignment'=>'pending'],'']]],'cash'=>['title'=>'Abhebung oder Einzahlung zuordnen','intro'=>'Verbinden Sie Bank und eigene Kasse. Geld zwischen eigenen Konten ist keine Einnahme oder Ausgabe.','steps'=>['Öffnen Sie den Bankumsatz und wählen Sie Vorhandenen Gegenumsatz auf eigenem Konto zuordnen.','Vergleichen Sie den tatsächlichen Gegenumsatz auf dem anderen eigenen Konto und bestätigen Sie die Zuordnung.','Fehlt die wirkliche Bargeldbewegung noch, erfassen Sie sie bewusst mit Handkasse, tatsächlichem Tag, Betrag und Grund. Bestätigen Sie, dass sie bereits erfolgt und noch nicht erfasst ist.','Gebühren erhalten einen eigenen Ausgabebeleg: Bei 100 Euro Bargeld und 3 Euro Gebühr werden 100 Euro als eigener Geldtransfer und 3 Euro als Ausgabe zugeordnet.','Diese Zuordnung überweist kein Geld und erfindet keine Barauszahlung. Sie verbindet tatsächlich erfolgte Bewegungen.'],'guard'=>['view'=>'finance','tab'=>'bank'],'links'=>[['Ausführliche Finanzhilfe öffnen',['view'=>'finance','tab'=>'help'],'eigene-geldtransfers']]],'invoices'=>['title'=>'Rechnung prüfen und bezahlen','intro'=>'Eine Überweisung beginnt an einer offenen Ausgabenrechnung oder freigegebenen Erstattung. Empfänger und Betrag bleiben an diesen Vorgang gebunden.','steps'=>['Öffnen Sie Finanzen → Rechnungseingang. Laden Sie die Originalrechnung hoch oder wählen Sie den vorhandenen Eingang.','Vergleichen Sie Rechnungssteller, Nummer, Datum und Betrag mit dem Original. Erfassen Sie den Zweck und eine gegebenenfalls bereits erfolgte Zahlung richtig.','Speichern ordnet die Datei dem Beleg zu. Die Freigabe durch eine aktuell berechtigte Person bleibt ein eigener Schritt.','Öffnen Sie am geprüften Beleg den passenden Zahlungsweg. Ordnen Sie eine vorhandene Zahlung zu oder bereiten Sie die gebundene Überweisung vor. Bei privater Vorleistung verwenden Sie die zugehörige Erstattung.','Ein vorbereiteter oder eingereichter Bankauftrag bestätigt noch keine Zahlung. Ordnen Sie anschließend den tatsächlich übernommenen Kontoumsatz zu.'],'guard'=>['view'=>'finance','tab'=>'inbox'],'links'=>[['Rechnungseingang öffnen',['view'=>'finance','tab'=>'inbox'],''],['Ausführliche Finanzhilfe öffnen',['view'=>'finance','tab'=>'help'],'finanzablauf']]],'members'=>['title'=>'Mitglieder aus Excel übernehmen','intro'=>'Die Vorlage erklärt ihre Spalten direkt in Excel. Vor der Übernahme werden alle Zeilen und mögliche Dubletten geprüft.','steps'=>['Öffnen Sie Mitglieder & Kontakte → Mitglieder → Excel: Import & Export und wählen Sie Excel-Vorlage mit Anleitung herunterladen.','Lesen Sie zuerst Anleitung. Tragen Sie eine Person pro Zeile ausschließlich im Blatt Mitglieder ein. Name und Eintritt sind Pflichtangaben; Beispiel ist nur eine Hilfe.','Lassen Sie eine unbekannte Mitgliedsnummer leer. Führende Nullen bleiben Text. Ist nur das Eintrittsjahr bekannt, tragen Sie dieses Jahr ein und erfinden kein Datum.','Tragen Sie bei Bedarf vollständige IBAN und Kontoinhaber ein. Die verschlüsselte Bankdatenübernahme benötigt Bankverwaltungsrechte, das eigene Konto-Passwort und gegebenenfalls den zweiten Faktor; sie erteilt kein Mandat.','Verwenden Sie für jede neue Familie eine gemeinsame ausdrückliche Familienkennung, einen einheitlichen Namen und genau einen mit ja markierten Beitragszahler. Für eine bestehende Familie verwenden Sie ihre ID-Kennung aus dem Export.','Der Jahresbeitrag muss zum eingerichteten Einzel- oder Familientarif passen. Leer verwendet den normalen Tarif; enthaltene Angehörige haben 0. Abweichende Beiträge werden zur Klärung markiert.','Laden Sie die ausgefüllte XLSX oder CSV und prüfen Sie Tabellenblatt, Kopfzeile und Spaltenzuordnung. Lesen Sie die vollständige Vorschau und klären Sie Konflikte und Dubletten vor der ausdrücklichen Übernahme.','Bestehende Profile werden nicht still überschrieben. Eine gemeinsame Familien-E-Mail führt Personen nicht zusammen. Kontrollieren Sie die übernommenen Profile nach dem Import.','Der Mitgliederdatenexport umfasst alle passenden Ergebnisseiten bis 999 Personen pro Datei. Er enthält private Mitgliedsdaten; wählen Sie die passende Gruppe und Suche bewusst.','Der normale Mitgliederdatenexport lässt Bankspalten leer. Vollständige Kontodaten benötigen die gesonderte Exportauswahl mit eigener persönlicher Bestätigung. Familienkennung, Zahler und aktueller Jahresbeitrag sind enthalten.'],'guard'=>['view'=>'members','list'=>'members'],'links'=>[['Excel: Import & Export öffnen',['view'=>'members','import'=>'1'],'',true],['Mitgliederliste öffnen',['view'=>'members','list'=>'members'],'']]],'profile'=>['title'=>'Mein Profil und meine Belege','intro'=>'Sie finden Ihre eigenen Vereinsangaben und ausgegebenen Belege im Vereinsportal.','steps'=>['Öffnen Sie Vereinsportal → Mein Profil & Belege. Prüfen Sie, dass Ihr Zugang dem richtigen persönlichen Profil zugeordnet ist.','Meine Belege zeigt Ihre verfügbaren ausgestellten Originale. Das Öffnen oder Herunterladen bestätigt keine Zahlung.','Ist noch kein Profil zugeordnet oder fehlen Unterlagen, wenden Sie sich an die Vereinsverwaltung. Eine gemeinsame E-Mail ist keine automatische persönliche Zuordnung.'],'guard'=>['view'=>'portal','tab'=>'own'],'links'=>[['Mein Profil öffnen',['view'=>'portal','tab'=>'own'],''],['Meine Belege öffnen',['view'=>'portal','tab'=>'documents'],'']]],'access'=>['title'=>'Zugang, Sprache und Rechte','intro'=>'Ein fehlender Menüpunkt hängt oft mit den aktuellen Rechten zusammen. Ihre persönliche Sprache wird am eigenen Konto eingestellt.','steps'=>['Prüfen Sie zuerst den angemeldeten Verein und den eigenen Zugang. Konten und Berechtigungen werden nicht aus einem gemeinsamen Namen oder einer E-Mail abgeleitet.','Öffnen Sie Mein Konto, um die persönlichen Konto- und Spracheinstellungen zu prüfen. Geben Sie Passwörter, zweite Faktoren und Bankzugänge nicht an andere Personen weiter.','Für fehlende Bearbeitungsrechte wenden Sie sich an die zuständige Vereinsverwaltung. Lesen, Bearbeiten, Freigeben und Bankaktionen können unterschiedliche Rechte benötigen.','Bei einer Fehlermeldung bleiben die ursprünglich angefragten Angaben wichtig. Lesen Sie den aktuellen Stand bewusst neu und bestätigen Sie einen neuen Vorgang anschließend gesondert.'],'guard'=>['view'=>'help'],'links'=>[['Mein Konto öffnen',['view'=>'settings','tab'=>'account'],'']]],'member-bank'=>['title'=>'Persönliche Bankdaten und SEPA','intro'=>'Eine hinterlegte Bankverbindung und ein SEPA-Mandat sind getrennte Entscheidungen. Hier wird kein Geld überwiesen.','steps'=>['Öffnen Sie Vereinsportal → Bankverbindung & SEPA. Prüfen Sie den angezeigten Namen. Die berechtigte Verwaltung wählt das Mitglied bewusst über Name oder Mitgliedsnummer; es gibt keinen automatischen Ersatzkontakt.','Tragen Sie freiwillig Kontoinhaber, IBAN und gegebenenfalls BIC ein. Bestätigen Sie mit Ihrem persönlichen Konto-Passwort und dem eingerichteten zweiten Faktor. Bank-PIN und TAN gehören nicht in dieses Formular.','Nach dem Speichern erscheinen nur maskierte Angaben. Vollständige Angaben öffnen Sie über Bankdaten öffnen mit einer erneuten Sicherheitsprüfung. Zum Ändern und Speichern ist eine eigene neue Bestätigung nötig.','Ein Mandat darf nur das Mitglied selbst nach gesonderter SEPA-Einrichtung ausdrücklich erteilen. Prüfen Sie Zahlungsempfänger, Gläubiger-ID und Mandatstext. Eine geänderte Bankverbindung beendet das bisherige Mandat.','Mandat widerrufen beendet das Mandat; Bankdaten entfernen entfernt die aktuelle Verbindung. Frühere verschlüsselte Nachweise bleiben erhalten. Bei einem Fehler bleiben Eingaben und ursprünglicher Stand erhalten, Passwort und Code bleiben leer. Prüfen Sie den aktuellen Stand bewusst vor einer neuen Bestätigung.'],'guard'=>['view'=>'portal','tab'=>'bank'],'links'=>[['Persönlichen Bankbereich öffnen',['view'=>'portal','tab'=>'bank'],'']]],'member-card'=>['title'=>'Mitgliederausweis, QR-Code und Wallet','intro'=>'Der Ausweis gehört zu einer bestimmten aktuellen Mitgliedschaft. Sein QR-Code bestätigt die gegenwärtige Gültigkeit und bezahlt keinen Beitrag.','steps'=>['Öffnen Sie Vereinsportal → Mitgliederausweis. Für die berechtigte Verwaltung führt auch das gewählte Mitgliederprofil zum richtigen Ausweis. Prüfen Sie Name, Mitgliedsnummer und Mitgliedschaft.','Wählen Sie beim Erstellen oder Erneuern Gültig bis und bestätigen Sie ausdrücklich die öffentliche Namensanzeige bei der QR-Prüfung. Der Ausweis gilt höchstens ein Jahr und nicht länger als die bekannte Mitgliedschaft.','Druckansicht öffnen zeigt die druckbare Karte. Ein QR-Scan zeigt nur Name, Verein und aktuelle Gültigkeit. Er verbraucht den Ausweis nicht und zeigt keine Bank-, Beitrags- oder Kontaktdaten.','Bei Verlust verwenden Sie Ausweis sperren mit einem Grund. Eine bewusste Erneuerung ersetzt den alten QR-Code; frühere Ausgaben bleiben im Ausweisverlauf. Prüfen Sie nach einem Konflikt die ursprünglichen Angaben erneut.','Apple Wallet und Google Wallet erscheinen erst nach passender Einrichtung und Prüfung durch den Verein. Nach einer Erneuerung laden Sie den neuen Ausweis erneut. Bereits gespeicherte Wallet-Karten werden nicht automatisch ausgetauscht.'],'guard'=>['view'=>'portal','tab'=>'card'],'links'=>[['Mitgliederausweis öffnen',['view'=>'portal','tab'=>'card'],''],['Mitgliederprofil auswählen',['view'=>'members','list'=>'members'],'']]],'editorial'=>['title'=>'Beiträge und Newsletter im Monatskalender planen','intro'=>'Social Media und Newsletter verwenden einen gemeinsamen Kalender. Sichtbare Kanäle und verfügbare Aktionen richten sich nach Ihren aktuellen Rechten.','steps'=>['Öffnen Sie Social Media & Newsletter → Planung. Wählen Sie den Monat und prüfen Sie für jeden Eintrag Datum, Kanal, Beitragsart und Status. Beitrag, Reel, Story und Newsletter sind gesondert gekennzeichnet.','Öffnen Sie den tatsächlichen Eintrag. Prüfen Sie Inhalt, Medien, Freigaben und geplanten Zeitpunkt. Ein Entwurf oder Kalendereintrag bestätigt keine Veröffentlichung und keinen Newsletter-Versand.','Prüfen Sie automatische Story-Vorbereitung und weitere Automatik unter Vorbereitung. Eine Vorbereitung ist noch keine Veröffentlichung. Geänderte Ausgangsinhalte und fehlende Rechte müssen vor einer neuen Freigabe geklärt werden.','Vergleichen Sie nach einem geplanten Lauf die tatsächlichen Kanal- oder Empfängerergebnisse im Verlauf. Ausstehend, fehlgeschlagen und bestätigt sind unterschiedliche Zustände. Beheben Sie den genannten Fehler vor einem bewussten erneuten Versuch.','Für Instagram, Facebook, StadtLand.Funk und weitere Anbieter werden gültige Vereinsverbindungen und Veröffentlichungsrechte benötigt. Eventbrite übernimmt den Facebook-Veranstaltungsweg extern; ohne Eventbrite wird der Facebook-Termin manuell angelegt. Der eigene Vereinstermin bleibt getrennt.','Veranstaltung auswählen öffnet eine eigene Auswahl und erhält ungespeicherte Texte. Nach einer unterbrochenen Übernahme bleiben Auswahl und ursprünglicher Vorgang erhalten. Ergebnis prüfen legt keinen Entwurf an; unverändert wiederholen öffnet denselben bestätigten Entwurf. Weiteren eigenen Entwurf vorbereiten ist eine bewusste neue Übernahme.'],'guard'=>['view'=>'social'],'links'=>[['Gemeinsamen Monatskalender öffnen',['view'=>'social','section'=>'planning'],'']]],'system-status'=>['title'=>'Systemstatus und Verbindungen prüfen','intro'=>'Einrichtung und aktuell bestätigte Verfügbarkeit sind getrennt. Eine Statusprüfung versendet keine Nachricht und löst keine Zahlung aus.','steps'=>['Öffnen Sie Einstellungen → Systemstatus. Wählen Sie System, Social & Termine, Zahlungen, Mail & Push oder Steuer & Bank. Prüfen Sie Zustand und tatsächlichen Prüfzeitpunkt. Ein veralteter Nachweis ist keine aktuelle Verbindungsbestätigung.','Prüfen aktualisiert nur den gewählten Dienst. Mit JavaScript bleibt die Einstellungsauswahl auf derselben Seite erhalten. Ohne JavaScript öffnet sich das Ergebnis in einem neuen Tab; die ungespeicherte Auswahl bleibt im ursprünglichen Tab.','Verlauf zeigt die Nachweise für die aktuelle Verbindung. Geänderte Konten oder Zugänge übernehmen kein altes Grün. Vorhandene Bank- und Zeitplannachweise werden nur gelesen; das startet keinen Bankabruf oder Versandlauf.','Öffnen Sie Status-Einstellungen, um automatische Prüfungen bewusst einzuschalten, Dienste zu pausieren oder die öffentliche Statusseite mit ausdrücklich gewählten Diensten freizugeben. Speichern bestätigt diese Auswahl gesondert.','Bei einem Fehler bleiben die ursprüngliche Auswahl und ihr Stand erhalten. Nach einem Versionskonflikt oder unklaren Ergebnis öffnen Sie Aktuelle Status-Einstellungen öffnen, vergleichen den gespeicherten Stand und bestätigen erst danach einen neuen Vorgang. Eine fehlende Berechtigung benötigt die zuständige Vereinsverwaltung.'],'guard'=>['view'=>'settings','tab'=>'status'],'links'=>[['Systemstatus öffnen',['view'=>'settings','tab'=>'status'],'']]],'technical-settings'=>['title'=>'Cache und Erweiterungen verwalten','intro'=>'Diese technischen Einstellungen benötigen einen aktuell berechtigten technischen Zugang. Allgemeine Einstellungsrechte allein reichen nicht aus.','steps'=>['Öffnen Sie Einstellungen → Cache, wenn eine zwischengespeicherte Ansicht erneuert werden muss. Prüfen Sie zuerst Speicher, Bereich und Zustand. Wählen Sie nur den passenden Bereich und die bewusst benötigte Aktion.','Öffnen Sie Einstellungen → Erweiterungen für die tatsächlich vorhandenen Pakete. Prüfen Sie Zustand und Version. Installation, Aktivierung, Aktualisierung und Deaktivierung sind getrennte bewusste Aktionen. Eine verfügbare Erweiterung ist noch nicht aktiv.','Öffnen Sie die Einstellungen der gewählten installierten Erweiterung. Prüfen Sie alle Felder und speichern Sie die gewünschte Auswahl ausdrücklich. Die Angaben einer anderen Erweiterung werden nicht übernommen.','Bei einem Versionskonflikt, geänderten Paketdateien oder unklarem Ergebnis bleiben die ursprünglichen Angaben zur Prüfung erhalten. Öffnen Sie den aktuellen Stand über den angebotenen Link bewusst neu, vergleichen Sie ihn und bestätigen Sie erst danach einen neuen Vorgang.','Der Erweiterungsverlauf zeigt frühere Aktionen. Eine fehlerhafte aktive Erweiterung kann bewusst deaktiviert werden. Fehlende Rechte klärt die zuständige Vereinsverwaltung; die Hilfe erteilt keine zusätzlichen Rechte.'],'guard'=>['view'=>'settings','tab'=>'cache'],'links'=>[['Cache öffnen',['view'=>'settings','tab'=>'cache'],''],['Erweiterungen öffnen',['view'=>'settings','tab'=>'extensions'],'']]],'api-access'=>['title'=>'Persönliche API-Zugänge verwalten','intro'=>'Ein API-Zugang gehört zu deinem persönlichen Konto. Er erhält nur ausgewählte Freigaben und bleibt an deine aktuellen Vereinsrechte gebunden.','steps'=>['Öffne Einstellungen → API-Zugänge. Prüfe zuerst vorhandene Zugänge, Gültigkeit und Freigaben. Ein Seitenaufruf legt keinen Zugang an.','Wähle für einen neuen Zugang eine eindeutige Bezeichnung, die benötigte Gültigkeit und ausschließlich die erforderlichen Freigaben. Bestätige mit deinem persönlichen Passwort und dem eingerichteten zweiten Faktor.','Der geheime Zugang wird nach erfolgreicher Anlage genau einmal angezeigt. Kopiere ihn in die vorgesehene Anwendung und bewahre ihn sicher auf. Ohne JavaScript kannst du ihn manuell markieren und kopieren.','Nach einem unklaren Ergebnis bleiben die ursprünglichen Angaben gesperrt. Öffne Aktuelle API-Zugänge öffnen, prüfe den gespeicherten Stand und widerrufe bei Bedarf einen nicht mehr nutzbaren Zugang. Lege erst danach bewusst einen neuen Zugang an.','Widerrufen beendet den ausgewählten eigenen Zugang. Abgelaufene oder widerrufene Zugänge werden nicht erneut aktiviert. Teile weder Zugangsschlüssel noch Passwort oder Sicherheitscode mit anderen Personen.'],'guard'=>['view'=>'settings','tab'=>'api'],'links'=>[['API-Zugänge öffnen',['view'=>'settings','tab'=>'api'],'']]],'local-system'=>['title'=>'Lokale Systemaufgaben verwalten','intro'=>'Zeitplan, persönlicher Auftrag und tatsächlich bestätigte Ausführung sind getrennte Schritte. Die Systemverwaltung benötigt aktuelle technische Verwaltungsrechte.','steps'=>['Öffne Einstellungen → Systemverwaltung → Lokale Aufgaben. Prüfe Aufgabe, Zustand und Intervall. Die vorhandenen Aufgaben bereinigen Websitecache oder abgelaufene eigene Anmeldedaten und pflegen Betriebsnachweise.','Wähle das Intervall, setze Zeitplan ausdrücklich aktivieren und speichere bewusst. Entferne den Aktivierungshaken und speichere, um zu pausieren. Beim nächsten privaten Lauf prüfen fordert nur die nächste Prüfung an; der Seitenaufruf führt sie nicht aus.','Vergleiche unter Lokale Läufe den tatsächlichen Ausführungsstand und die Rückmeldung. Unter Betriebshinweise bestätigt Hinweis bestätigen den ausgewählten Hinweis nur für dein eigenes Konto. Eine Bestätigung ist keine fachliche Abnahme.','Bei einem Versionskonflikt, fehlenden Rechten oder unbestätigten Ergebnis bleiben die ursprünglichen Angaben gesperrt lesbar. Aktuellen Stand neu öffnen liest den gespeicherten Stand. Prüfe ihn vor einer danach ausdrücklich bestätigten neuen Aktion.','Paket & Datenbank zeigt vorhandene Modul-, Migrations- und Paketnachweise. Diese Ansicht führt weder Installation noch Upgrade aus. Fehlende technische Rechte klärt die zuständige Vereinsverwaltung.'],'guard'=>['view'=>'settings','tab'=>'system'],'links'=>[['Systemverwaltung öffnen',['view'=>'settings','tab'=>'system'],'']]],'minutes'=>['title'=>'Protokolle schreiben und freigeben','intro'=>'Mitglieder lesen freigegebene Protokolle. Nur berechtigte Bearbeitende können Entwürfe schreiben, PDFs ersetzen und Freigaben ändern.','steps'=>['Öffne Protokolle und wähle das richtige Protokoll oder lege bewusst einen neuen Entwurf an. Entwürfe und archivierte Protokolle bleiben intern.','Trage Titel und Sitzungsdatum ein. Schreibe den Text direkt oder verwende eine Vorlage. Ohne JavaScript steht ein normales Textfeld bereit; unveränderter Text behält seine gespeicherte Formatierung.','Für ein fertiges PDF wähle PDF hochladen und die vollständige Originaldatei bis 10 MB. Nach einem Fehler muss eine zuvor gewählte Ersatzdatei erneut ausgewählt werden.','Speichere den Entwurf und prüfe die Vorschau. Bestätige die Freigabe ausdrücklich mit dem Haken. Rücknahme, Archivierung und Wiederherstellung bleiben jeweils eigene bestätigte Schritte.','Nach einem Konflikt oder unbestätigten Speicherergebnis bleiben die eigenen ursprünglichen Angaben erhalten. Öffne den gespeicherten Stand getrennt, vergleiche ihn und bestätige einen erneuten ursprünglichen Vorgang nur bewusst. Ein nicht gefundener Anlagevorgang erzeugt keinen neuen Entwurf.'],'guard'=>['view'=>'minutes'],'links'=>[['Protokolle öffnen',['view'=>'minutes'],'']]],'my-changes'=>['title'=>'Eigene Angaben zur Prüfung einreichen','intro'=>'Dein Änderungsantrag betrifft nur das dir zugeordnete Mitgliederprofil. Die bisherigen Angaben bleiben bis zur ausdrücklichen Übernahme erhalten.','steps'=>['Öffne Vereinsportal → Meine Angaben ändern. Prüfe zuerst, dass die angezeigten Angaben zu deiner Person gehören. Eine gemeinsame Familien-E-Mail ordnet dir kein anderes Profil zu.','Ändere Name, Kontakt-E-Mail, Telefon oder Anschrift und wähle Zur Prüfung einreichen. Anmeldename, Passwort und Passwort-Rücksetzadresse werden dadurch nicht geändert.','Öffne den gespeicherten Antrag und prüfe die ursprünglichen und vorgeschlagenen Angaben. Solange ein Antrag offen ist, reiche keine zweite Änderung ein; du kannst den ursprünglichen Antrag ausdrücklich zurückziehen.','Der Vorstand übernimmt die geprüften Angaben oder hinterlegt eine begründete Ablehnung. Lies die Rückmeldung am ursprünglichen Antrag. Nach dem Abschluss kannst du bewusst eine neue Änderung vorschlagen.','Nach einem Konflikt oder unbestätigten Ergebnis bleiben die ursprünglichen Eingaben erhalten. Prüfe den gespeicherten Antrag oder Einreichungsvorgang in einem anderen Fenster. Eine fehlende Speicherung erzeugt keinen Ersatzantrag; ein geänderter Profilbezug wird nicht übernommen.'],'guard'=>['view'=>'portal','tab'=>'changes'],'links'=>[['Eigene Änderungsanträge öffnen',['view'=>'portal','tab'=>'changes'],'']]],'review-changes'=>['title'=>'Mitgliederänderungen vergleichen und entscheiden','intro'=>'Die Prüfung benötigt aktuelle Vorstands- oder Superuser-Rechte und Mitglieder-Schreibrecht. Sie verändert nur die vorgeschlagenen Kontaktdaten.','steps'=>['Öffne Mitglieder & Kontakte → Mitgliederänderungen prüfen. Suche bei Bedarf nach dem Mitglied und wähle den ursprünglichen Antrag bewusst aus.','Vergleiche Bei Einreichung, Vorgeschlagen und gegebenenfalls Inzwischen im Profil. Eine nachträglich geänderte Person oder Mitgliedschaft darf nicht mit alten Angaben überschrieben werden.','Setze die ausdrückliche Bestätigung und wähle Geprüfte Angaben übernehmen. Bei Nicht übernehmen ist eine verständliche Rückmeldung erforderlich. Eine Übernahme ändert keinen Anmeldenamen und keine Bankverbindung.','Bei einem geänderten Profil oder einer beendeten Mitgliedschaft lehne den alten Antrag mit einer Begründung ab. Das aktuelle Mitglied kann nach dem Vergleich einen neuen eigenen Antrag stellen.','Nach einem Konflikt oder unbestätigten Speicherergebnis bleiben deine ursprüngliche Entscheidung und Rückmeldung erhalten. Öffne den gespeicherten Stand getrennt und vergleiche ihn vor einer bewusst bestätigten weiteren Aktion. Eine inzwischen getroffene Entscheidung wird nicht überschrieben.'],'guard'=>['view'=>'members','tab'=>'changes'],'links'=>[['Mitgliederänderungen prüfen öffnen',['view'=>'members','tab'=>'changes'],'']]],'report-tax'=>['title'=>'Finanzamtsbericht vorbereiten und freigeben','intro'=>'Der Finanzamtsbericht beschreibt die tatsächlichen Tätigkeiten und Satzungszwecke. Er bleibt vom Versammlungs- und Kassenbericht getrennt.','steps'=>['Öffne Dokumente → Tätigkeitsberichte und wähle die richtige Berichtsart. Prüfe den tatsächlichen Zeitraum von höchstens drei aufeinanderfolgenden Jahren.','Mit Vorbereitungsrecht ergänze die Angaben und wähle Bericht aus Tätigkeiten vorbereiten. Eine alte Formularseite darf keinen inzwischen geänderten Bericht oder dessen Freigabe ersetzen.','Als aktuell zugeordneter 1. Vorstand öffne Bericht bearbeiten. Speichere deinen Text zuerst. Die getrennte Textbearbeitung bietet keine PDF-Freigabe an.','Öffne im gespeicherten Bericht Gespeicherten Bericht als PDF ansehen. Eine eigene hinterlegte Unterschrift bleibt eine ausdrückliche Wahl. Prüfe das vollständige PDF und bestätige erst danach Bericht freigeben. Leseberechtigte können ein unsigniertes PDF prüfen.','Nach einem Konflikt oder unbestätigten Ergebnis behalte die ursprünglichen Angaben. Öffne den gespeicherten Bericht oder Zeitraum getrennt und prüfe das tatsächliche Ergebnis vor einer bewusst bestätigten Wiederholung. Eine geänderte Unterschrift, Quelle oder Vorstandszuordnung benötigt eine neue PDF-Prüfung.'],'guard'=>['view'=>'documents','tab'=>'activity-reports','report_kind'=>'tax'],'links'=>[['Finanzamtsbericht vorbereiten und freigeben',['view'=>'documents','tab'=>'activity-reports','report_kind'=>'tax'],'']]],'report-assembly'=>['title'=>'Versammlungsbericht vorbereiten und freigeben','intro'=>'Der Versammlungsbericht enthält Rückblick, Vereinsentwicklung, Dank und Ausblick. Er bleibt vom Finanzamts- und Kassenbericht getrennt.','steps'=>['Öffne Dokumente → Tätigkeitsberichte und wähle die richtige Berichtsart. Prüfe den tatsächlichen Zeitraum von höchstens drei aufeinanderfolgenden Jahren.','Mit Vorbereitungsrecht ergänze die Angaben und wähle Bericht aus Tätigkeiten vorbereiten. Eine alte Formularseite darf keinen inzwischen geänderten Bericht oder dessen Freigabe ersetzen.','Als aktuell zugeordneter 1. Vorstand öffne Bericht bearbeiten. Speichere deinen Text zuerst. Die getrennte Textbearbeitung bietet keine PDF-Freigabe an.','Öffne im gespeicherten Bericht Gespeicherten Bericht als PDF ansehen. Eine eigene hinterlegte Unterschrift bleibt eine ausdrückliche Wahl. Prüfe das vollständige PDF und bestätige erst danach Bericht freigeben. Leseberechtigte können ein unsigniertes PDF prüfen.','Nach einem Konflikt oder unbestätigten Ergebnis behalte die ursprünglichen Angaben. Öffne den gespeicherten Bericht oder Zeitraum getrennt und prüfe das tatsächliche Ergebnis vor einer bewusst bestätigten Wiederholung. Eine geänderte Unterschrift, Quelle oder Vorstandszuordnung benötigt eine neue PDF-Prüfung.'],'guard'=>['view'=>'documents','tab'=>'activity-reports','report_kind'=>'assembly'],'links'=>[['Versammlungsbericht vorbereiten und freigeben',['view'=>'documents','tab'=>'activity-reports','report_kind'=>'assembly'],'']]]];

 public static function contextRoute(WorkspaceAccess $access,string $view,string $tab,array $query=[]):array
 {
  $reportKind=array_key_exists('report_kind',$query)?$query['report_kind']:'tax';$reportTopic=match($reportKind){'tax'=>'report-tax','assembly'=>'report-assembly',default=>null};
  $topic=match(true){$view==='calendar'=>'calendar',$view==='inventory'=>'inventory',$view==='chat'=>'chat',$view==='press'=>'press',$view==='website'=>'website',$view==='finance'&&in_array($tab,['tax','export','reports','book-values'],true)=>'year-end',$view==='documents'&&$tab==='activity-reports'=>$reportTopic,$view==='members'&&$tab==='changes'=>'review-changes',$view==='portal'&&$tab==='changes'=>'my-changes',$view==='minutes'=>'minutes',$view==='members'=>'members',$view==='finance'&&in_array($tab,['','bank'],true)=>'bank',$view==='finance'&&in_array($tab,['inbox','receipts','outgoing'],true)=>'invoices',$view==='portal'&&$tab==='bank'=>'member-bank',$view==='portal'&&$tab==='card'=>'member-card',$view==='portal'=>'profile',$view==='social'&&in_array($query['section']??null,['inbox','review','replies','mail','sync'],true)=>'social-conversations',in_array($view,['social','newsletter'],true)=>'editorial',$view==='settings'&&$tab==='status'=>'system-status',$view==='settings'&&$tab==='api'=>'api-access',$view==='settings'&&$tab==='system'=>'local-system',$view==='settings'&&in_array($tab,['cache','extensions'],true)=>'technical-settings',$view==='settings'&&$tab==='account'=>'access',default=>null};
  return ['view'=>'help']+($topic!==null&&$access->allows(self::TOPICS[$topic]['guard'])?['help_topic'=>$topic]:[]);
 }
 public static function prepare(WorkspaceAccess $access,bool $membersWrite,bool $financeWrite,array $query):array
 {
  $out=['state'=>'index','status'=>200,'topics'=>[],'selected'=>null,'raw_present'=>array_key_exists('help_topic',$query),'raw'=>$query['help_topic']??null,'message'=>''];
  if(!$access->allows(['view'=>'help'])){$out['state']='blocked';$out['status']=403;$out['message']='Für dieses Thema fehlt der aktuelle Zugriff. Die Hilfeübersicht zeigt Ihre verfügbaren Aufgaben.';return$out;}
  foreach(self::TOPICS as$id=>$topic){if(!$access->allows($topic['guard']))continue;$topic['links']=array_values(array_filter($topic['links'],static fn($link)=>($membersWrite||!($link[3]??false))&&$access->allows($link[1])));$topic['can_edit']=match($id){'members'=>$membersWrite,'bank','cash','invoices'=>$financeWrite,default=>true};$out['topics'][$id]=$topic;}
  if(!$out['raw_present'])return$out;
  if(!is_string($out['raw'])||!array_key_exists($out['raw'],self::TOPICS)){$out['state']='invalid';$out['status']=422;$out['message']='Die ursprüngliche Themenauswahl ist nicht verwendbar. Bitte die vollständige Angabe prüfen und die Hilfeübersicht ausdrücklich öffnen.';}
  elseif(!isset($out['topics'][$out['raw']])){$out['state']='blocked';$out['status']=403;$out['message']='Für dieses Thema fehlt der aktuelle Zugriff. Die Hilfeübersicht zeigt Ihre verfügbaren Aufgaben.';}
  else{$out['state']='selected';$out['selected']=$out['topics'][$out['raw']];}
  return$out;
 }
}
